namespace loam {
namespace {

// Markers (low/high/has_absent/region_low/region_high) are only trustworthy
// on faithfully written slabs. Archived mixed-generation slabs (older
// generations) carry incomplete markers, so selective admission must not skip
// them; the reader opens them and lets the exact per-cell scan decide.
constexpr std::uint8_t kFaithfulGeneration = 3;

bool markers_faithful(const Slab& a) {
    return a.generation >= kFaithfulGeneration;
}

}  // namespace

Gate turn_b(const Slab& a, const Probe& b) {
    if (!b.skipping) {
        return {true, "full"};
    }
    if (b.op == Op::All) {
        return {true, "all"};
    }
    if (!markers_faithful(a)) {
        return {true, "unfaithful-markers"};
    }
    if (b.op == Op::IsNull) {
        return {a.has_absent, a.has_absent ? "possible" : "empty"};
    }
    if (b.op == Op::RegionEqual) {
        const bool read = b.text >= a.region_low && b.text <= a.region_high;
