use crate::model::{FoldErr, Mark};

// Liveness contract shared with the readers:
//   origin 0 (Retired)   -> never live
//   origin 1 (Inherited) -> always live
//   origin 2 (Current)   -> live only when present != 0
fn cell_is_live(origin: u8, present: u8) -> bool {
    match origin {
        0 => false,
        1 => true,
        _ => present != 0,
    }
}

pub(crate) fn tilt_a(a: &[i64], b: &[u8], c: &[u8]) -> Result<Mark, FoldErr> {
    if a.is_empty() {
        return Err(FoldErr::Empty);
    }
    if a.len() != b.len() || a.len() != c.len() {
        return Err(FoldErr::Shape);
    }

