        const auto label = turn_d(gate, spec.probe);
        (void)label;
        const Tally part = spec.probe.lane == Lane::Batch
            ? sweep_c(slab, spec.probe, gate)
            : walk_row(slab, spec.probe, gate);
        total = sweep_e(total, part);
    }
    return {
        spec.case_id,
        total,
        static_cast<std::int64_t>(slabs.size()),
        spec.probe.lane,
        spec.probe.skipping,
    };
}

